"""Global eight-charge QC family generated by the verified C0 stabilizer.

Exact rational algebra only. The heat theorem in heat/ is its governing
analytic premise. This is a basis of CUBIC POLYNOMIALS, not a finite
catalogue of fields or covariance directions.
"""
from pathlib import Path
from fractions import Fraction as R
from itertools import product
import json
HERE=Path(__file__).resolve().parent

def construct(d,b,ca,r):
 F,C0,T=r.m.acquired();qc=json.loads((HERE.parent/'quadratic_boundary/certificate.json').read_text());ac=json.loads((HERE.parent/'acoustic_capacity/certificate.json').read_text());op=[list(map(R,row)) for row in qc['normal_form_operator']];jet=[list(map(R,row)) for row in ac['jet_operator_on_normal_basis']];charge=ca.mm(jet,op);A=[b.var(4,i) for i in range(4)];GA=[[R(0)]*4 for _ in range(4)]
 for i,(j,s) in enumerate(zip((3,2,1,0),(1,-1,1,-1))):GA[i][j]=R(s)
 rots=[(R(1),R(0)),(R(0),R(1)),(R(3,5),R(4,5)),(R(-4,5),R(3,5))];rows=[];polys=[];metadata=[]
 for gamma,(x,y) in product((0,1),rots):
  UA=[[x,0,-y,0],[0,x,0,-y],[y,0,x,0],[0,y,0,x]]
  if gamma:UA=ca.mm(UA,GA)
  images=[b.add(*(b.scale(p,c) for p,c in zip(A,row))) for row in UA];C=r.compose(C0,images,4);assert r.compose(F,images,4)==F and r.compose(T,images,4)==T;polys.append(C);rows.append([C.get(tuple(pw),R(0)) for pw in d['powers']]);metadata.append({'Gamma':gamma,'rotation':list(map(str,(x,y)))})
 J=ca.transpose(rows);Z=ca.mm(charge,J);assert b.rank(Z)==8;Zi,_=ca.solve_range(Z,[[R(int(i==j)) for j in range(8)] for i in range(8)]);K=ca.scale(ca.mm(ca.transpose(Zi),Zi),8*4096);b.pd(K);U=ca.mm(J,Zi);assert ca.mm(charge,U)==[[R(int(i==j)) for j in range(8)] for i in range(8)]
 # The new scalar ellipsoid is strictly stronger in every charge direction.
 b.pd(ca.add(ca.scale(d['coefficient_Gram'],R(2**112)),ca.scale(K,-1)))
 delta=ca.add(U,ca.scale(d['charge_representatives'],-1));tm=d['translations'];TT=ca.mm(ca.transpose(tm),tm);offset,_=ca.solve_range(TT,ca.mm(ca.transpose(tm),delta));assert ca.mm(tm,offset)==delta
 # Check the explicit translation transport for every canonical unit charge
 # and every translation. It produces F+C+Q up to affine terms exactly.
 def stabilize(cvec):
  coords=[sum(a*v for a,v in zip(row,cvec)) for row in op];assert [sum(a*v for a,v in zip(row,coords)) for row in ca.transpose(d['basis'])]==list(cvec)
  z=[sum(a*v for a,v in zip(row,cvec)) for row in charge];t=[sum(a*v for a,v in zip(row,z)) for row in Zi];cJ=[sum(a*v for a,v in zip(row,t)) for row in J];gap=[a-v for a,v in zip(cvec,cJ)];hh,_=ca.solve_range(tm,[[x] for x in gap]);hh=[row[0] for row in hh];C={tuple(pw):v for pw,v in zip(d['powers'],cvec) if v};CJ={tuple(pw):v for pw,v in zip(d['powers'],cJ) if v};kappa=R(4096)*sum(map(abs,t))**2
  Q=b.add(b.scale(T,kappa),*(b.scale(d['HF'][i][j],hh[i]*hh[j]/2) for i in range(4) for j in range(4)),*(b.scale(b.diff(CJ,i),hh[i]) for i in range(4)))
  shifted=[b.add(A[i],{(0,0,0,0):hh[i]}) for i in range(4)];translated=r.compose(b.add(F,CJ,b.scale(T,kappa)),shifted,4);residual=b.add(translated,b.scale(b.add(F,C,Q),-1));assert all(sum(pw)<=1 for pw in residual)
  return {'quadratic':Q,'orbit_coordinates':t,'argument_translation':hh,'scalar_stabilizer':kappa}
 for col in ca.transpose(d['charge_representatives']):stabilize(col)
 for col in ca.transpose(tm):stabilize(col)
 C0vec=[C0.get(tuple(pw),R(0)) for pw in d['powers']];s0=stabilize(C0vec);assert s0['quadratic']==b.scale(T,4096)
 raw={'governing_heat_coefficient':4096,'orbit_parameters':metadata,'orbit_cubic_coefficients':[list(map(str,row)) for row in rows],'charge_matrix':[list(map(str,row)) for row in Z],'charge_inverse':[list(map(str,row)) for row in Zi],'unit_charge_representatives':[list(map(str,row)) for row in ca.transpose(U)],'QC_quadratic_coefficient_Gram':[list(map(str,row)) for row in K],'translation_offsets_from_minimal_coefficient_gauge':[list(map(str,row)) for row in offset],'charge_rank':8,'old_ellipsoid_minus_new_ellipsoid_Gram_positive_definite':True,'scope':'Every real eight-charge parameter gives a globally QC polynomial. All actual periodic L4 gradients obey the resulting compatibility matrix. This does not establish an attainable capacity allocation for every field.'}
 (HERE/'orbit_bound.json').write_text(json.dumps(raw,indent=2)+'\n')
 return {'K':K,'section':U,'J':J,'Z':Z,'Zi':Zi,'orbit_polynomials':polys,'stabilize':stabilize}
